SELECT '#auth'; SELECT AUTH_ID, AUTH_TYPE, AUTH_ATTR, USE_YN FROM ju_auth ORDER BY AUTH_ID;
SELECT '#cols'; SELECT TABLE_NAME, ORDINAL_POSITION, COLUMN_NAME, COLUMN_TYPE, IS_NULLABLE, COLUMN_DEFAULT, COLUMN_COMMENT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_client','ju_client_detail','ju_auth') ORDER BY 1,2;
SELECT '#keys'; SELECT TABLE_NAME, INDEX_NAME, NON_UNIQUE, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_client','ju_client_detail') GROUP BY 1,2,3 ORDER BY 1,2;
SELECT '#fks'; SELECT TABLE_NAME, CONSTRAINT_NAME, REFERENCED_TABLE_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_client','ju_client_detail') AND REFERENCED_TABLE_NAME IS NOT NULL ORDER BY 1,2;
